# Reconstruct both demos and their stated outputs for an explicit full-grid check.
def blank(h,w): return [[0]*w for _ in range(h)]
def put(g,r,coords,col):
 for c in coords:g[r][c]=col
# Demo 1
D1=blank(17,13)
for r in (1,2,3):
 for c,v in zip((2,3,4),(4,1,6)):D1[r][c]=v
shape1={7:[3,4,5,6],8:[3,6],9:[1,2,3,6,7,8],10:[2,3,6,7],11:[2,3,4,5,6,7]}
shape1b={12:[3,4,5,6],13:[3,6],14:[1,2,3,6,7,8],15:[2,3,6,7],16:[2,3,4,5,6,7]}
for r,cs in shape1.items():put(D1,r,cs,1)
for r,cs in shape1b.items():put(D1,r,cs,6)
E1=blank(17,13)
for r in range(2,7):
 for c,v in [(2,4),(3,4),(4,4)]: pass
# figure local mask is rows 7..11, cols1..8
for i,(rr,cs) in enumerate(shape1.items()):
 for c in cs:E1[rr-5][c]=4
for r,cs in shape1.items():put(E1,r,cs,1)
for r,cs in shape1b.items():put(E1,r,cs,6)
# Demo 2
D2=blank(18,14)
for r in (1,2,3):
 for c,v in zip((7,8,9,10),(7,2,1,3)):D2[r][c]=v
shape2={8:[3,6],9:[2,3,4,5,6,7],10:[4,5]}
for r,cs in shape2.items():put(D2,r,cs,2)
for r,cs in {r+3:cs for r,cs in shape2.items()}.items():put(D2,r,cs,1)
E2=blank(18,14)
for col,top in [(7,5),(2,8),(1,11),(3,14)]:
 for dr,cs in shape2.items():put(E2,top+(dr-8),cs,col)
A1=mod.transform(D1); A2=mod.transform(D2)
print('demo1 exact',A1==E1,'demo2 exact',A2==E2)
if A1!=E1:
 print('d1 differing rows',[(i,A1[i],E1[i]) for i in range(17) if A1[i]!=E1[i]])
if A2!=E2:
 print('d2 differing rows',[(i,A2[i],E2[i]) for i in range(18) if A2[i]!=E2[i]])
